// src/util/wheelZoom.ts
var ZOOM_PER_NOTCH = 1.1;
var NOTCH_PX = 100;
var LINE_PX = 40;
var PAGE_PX = 800;
var PINCH_GAIN = 10;
var MAX_NOTCHES_PER_EVENT = 2;
function wheelZoomFactor(e) {
  const px = e.deltaY * (e.deltaMode === 1 ? LINE_PX : e.deltaMode === 2 ? PAGE_PX : 1);
  const notches = (e.ctrlKey ? PINCH_GAIN : 1) * px / NOTCH_PX;
  return ZOOM_PER_NOTCH ** -Math.max(-MAX_NOTCHES_PER_EVENT, Math.min(MAX_NOTCHES_PER_EVENT, notches));
}

export {
  wheelZoomFactor
};
